--

INSERT INTO `products` (`id`, `category_id`, `name`, `slug`, `small_description`, `description`, `original_price`, `selling_price`, `image`, `qty`, `status`, `created_at`, `profit_margin`) VALUES
(1, 25, '\"Dạy Con Trong Hoang Mang II\" - Carol S. Dweck', 'day-con-trong-hoang hoanhoang-mang-II-66-25-69', '\"Dạy Con Trong Hoang Mang II\" gửi gắm thông điệp chuyển hóa chính mình để giáo dục trẻ thơ.\r\n\r\nThông qua thông điệp để gửi đi một thông điệp khác biệt với những cuốn sách khác trên thị trường sách Việt Nam hiện nay: các bố mẹ cần chuyển hóa chính mình, “hòa giải” với quá khứ và những tổn thương của mình, để việc giáo dục con cái trở nên nhẹ nhàng, hiệu quả hơn. Đây chính là thông điệp chủ đạo xuyên suốt trong toàn bộ cuốn sách, và cũng chính là điều khiến bố mẹ Việt Nam đồng tình, chia sẻ giá trị của cuốn sách với nhiều người khác.', 'Dựa trên những phản hồi của bạn đọc thông qua giải pháp Social Books của Anbooks và tác giả Lê Nguyên Phương, bao gồm những thắc mắc hỏi rõ thêm và gợi ý về những chủ đề mới, sau khi về Mỹ, TS. Lê Nguyên Phương đã bắt tay vào thực hiện Dạy con trong “hoang mang” 2. Sách bao gồm 29 bài viết dựa trên trục các chủ đề được bố mẹ Việt Nam quan tâm, gửi thắc mắc và cần hỗ trợ. Có những chủ đề được phân tích, chia sẻ trong một bài viết, nhưng cũng có những chủ đề được chia sẻ thành nhiều bài liên tiếp. Từ câu chuyện “Thiên đàng đổ vỡ”, chia sẻ về nỗi đau của những đứa trẻ phải chứng kiến bạo hành trong gia đình, những di chứng về tâm hồn mà chúng phải gánh chịu; ảnh hưởng rõ rệt của các di chứng này trong đời sống của con cái; đến “Sau lời chia tay” nói về những tổn thương trẻ có thể hứng chịu do quá trình ly hôn của cha mẹ và những diễn biến trong tâm lý, hành vi của trẻ theo tiến trình thời gian sau khi sự việc xảy ra; từ câu chuyện hiểu sao cho đúng về phương pháp “tâm bình an”, “nuôi con an yên” theo phong trào đang rộ lên thời gian gần đây, chính là “khả năng tự phục hồi cảm xúc” trong khoa học, đưa ra một cái nhìn thấu đáo nhưng cũng thẳng thắn chỉ ra những “lỗ hổng” trong nhận thức của nhiều người về vấn đề này.\r\n\r\nCác chủ đề trong Dạy con trong “hoang mang” 2 mở rộng từ gia đình đến nhà trường, từ gia đình đến xã hội. Nếu “Để con nhảy múa” đề cập đến hiện tượng các bố mẹ đặt quá nhiều kỳ vọng và khuôn phép lên con mình, khiến con không được tự do sáng tạo và thoải mái như chính con đáng có, đến những câu chuyện lớn về nhân sinh quan của đời người như “Công ơn dưỡng dục”, nói về mối tương quan giữa con người với thế giới, với vạn vật, hay “Muối của đất công chính”, nói về ý thức liêm chính trong xã hội có thể bắt đầu từ khi trẻ còn rất nhỏ…', 399, 444, '9786045845851.jpg', 22, 0, '2026-03-08 07:00:00', 20.00),
(2, 23, '\"Cách sống\" - Inamori Kazuo', 'cach-song--inamori-kazuo', 'Cách sống là một cuốn sách truyền cảm hứng, mang đến cho người đọc những bài học quý báu về cách sống và phát triển bản thân.', 'Cách sống giống như một cây gậy đập vào dòng chảy xiết của thời đại u mê. Tại sao tình trạng u ám bế tắc đó bao trùm toàn xã hội? Đó phải chăng là do con người đánh mất phương hướng cuộc đời, không nhìn thấy ý nghĩa cũng như giá trị sống? điều cần thiết nhất trong thời đại như vậy là chúng ta phải đặt lại câu hỏi rất căn bản: “con người sống phải làm gì?\" \r\n\r\nVề cuốn sách là tác phẩm được dịch sang 8 thứ tiếng như tiếng Anh, tiếng Trung, tiếng Hàn Quốc… có sức ảnh hưởng rất lớn hiện nay và đang được thế giới chú ý. \r\n\r\nLà một cuốn nhân sinh luận mà nhà kinh doanh hàng đâu trên thế giới dành tặng cho tất cả mọi người: để có thể đạt được những giấc mơ lớn lao, để trải nghiệm một cuộc đời thực sự. ', 225, 270, '8935280917316.webp', 20, 0, '2026-03-08 07:00:00', 20.00),
(3, 22, '\"Hồ Điệp Và Kình Ngư\"- Tuế Kiến', 'ho-diep-va-kinh-ngu--tue-kien', '\"HỒ ĐIỆP VÀ KÌNH NGƯ - BI KỊCH HAY HUYỀN THOẠI CỦA TÌNH YÊU?\" \r\n\r\nMột câu chuyện cuốn hút ngay từ những trang đầu tiên - Khi tình yêu trở thành sợi dây mong manh giữa sinh tử, phản bội và hy vọng. Khi một nàng hồ điệp nhỏ bé chạm trán với kình ngư mạnh mẽ, liệu đó là định mệnh hay chỉ là một giấc mộng chóng tàn?', 'Một cô gái trẻ đang sống một cuộc đời bình thường nhưng lại vô tình bị cuốn vào thế giới đen tối đầy bí ẩn của một người đàn ông nguy hiểm nhưng đầy cuốn hút. Anh là kẻ đứng trên đỉnh cao quyền lực, là người mà cô không nên yêu. Nhưng càng muốn trốn chạy, càng không thể thoát. \r\n\r\nGiữa họ là yêu hay hận? Là bảo vệ hay hủy diệt? \r\nLà vận mệnh đã an bài hay chỉ là một trò đùa tàn nhẫn của số phận? \r\n\r\nNhững bí mật chôn giấu dần được phơi bày, những lựa chọn đau đớn buộc phải đưa ra. Khi đã bước vào ván cờ sinh tử này, liệu tình yêu có đủ để cứu rỗi cả hai?', 460, 552, 'ho-diep-va-kinh-ngu.webp', 39, 0, '2026-03-08 07:00:00', 20.00),
(4, 25, '\"Con Có Thể Tự Bảo Vệ Mình - Cơ Thể Con Là Của Con\" - Dagmar Geisler', 'con-co-the-tu-bao-ve-minh-co-the-con-la-cua-con--dagmar-geisler', 'Cuốn sách này giúp trẻ em hiểu rõ về cơ thể mình và cách bảo vệ bản thân khỏi các mối nguy hiểm.', 'Cuốn sách \"Con Có Thể Tự Bảo Vệ Mình - Cơ Thể Con Là Của Con\" là một tài liệu giáo dục quan trọng, giúp trẻ em nhận biết các mối nguy hiểm và học cách bảo vệ bản thân. Sách cung cấp những kiến thức cần thiết về sức khỏe, an toàn và vệ sinh cá nhân, đồng thời khuyến khích trẻ phát triển tư duy phản biện và khả năng tự bảo vệ. ', 140, 155, '8935325007934.webp', 19, 0, '2026-03-08 07:00:00', 20.00),
(5, 25, '\"Con Có Thể Tự Bảo Vệ Mình - Con Không Bao Giờ Đi Cùng Người Lạ\" - Dagmar Geisler', 'con-co-the-tu-bao-ve-minh-con-khong-bao-gio-di-cung-nguoi-la--dagmar-geisler', 'Cuốn sách này giúp trẻ em hiểu rõ về cơ thể mình và cách bảo vệ bản thân khỏi các mối nguy hiểm.', '“Con không bao giờ đi cùng người lạ” kể về: Giờ tan trường, trong khi hầu hết các bạn nhỏ đều được đón về chỉ còn mình Lu đứng trước cửa chờ đợi. Lu gặp những người quen đề nghị đưa Lu về nhưng Lu đã từ chối. Vì sao vậy? Bởi Lu không hề biết hết tất cả mọi thông tin về họ và Lu chỉ được phép đi cùng những người có trong danh sách cha mẹ cho phép.', 180, 200, '8935325007910.webp', 20, 0, '2026-03-08 07:00:00', 20.00),
(6, 25, '\"101 Tips - Giúp Con Kiểm Soát Cảm Xúc\" - Louise Baty', '101-tips-giup-con-kiem-soat-cam-xuc--louise-baty', 'Cuốn sách này cung cấp những mẹo vặt giúp trẻ em kiểm soát cảm xúc của mình.', 'Cuốn sách \"101 Tips - Giúp Con Kiểm Soát Cảm Xúc\" là một tài liệu hữu ích cho các bậc cha mẹ, giúp họ hiểu rõ hơn về cảm xúc của con cái và cách hỗ trợ trẻ phát triển kỹ năng quản lý cảm xúc. Sách cung cấp những lời khuyên thực tế và dễ áp dụng trong cuộc sống hàng ngày.', 108, 120, '8935074132628.webp', 22, 0, '2026-03-08 07:00:00', 20.00),
(7, 22, '\"Ngõ Ngô Đồng\" - Tống Triệt Không Thích Ăn Cá', 'ngo-ngo-dong', '\"Ngõ Ngô Đồng\" là câu chuyện tình yêu đầy day dứt và cảm động giữa Ninh Uyển và Tống Thanh Yến – người anh trai, người bảo hộ và cũng là ánh sáng duy nhất trong cuộc đời cô. Giữa những năm tháng thanh xuân đầy biến động, họ sưởi ấm cho nhau bằng sự chân thành, để rồi kết thúc bằng một sự hy sinh khắc cốt ghi tâm, để lại nỗi nhớ thương kéo dài suốt nhiều năm tháng về sau.', 'Câu chuyện bắt đầu vào năm Ninh Uyển 15 tuổi, khi cô gặp Tống Thanh Yến – bạn thân của anh trai mình. Với vẻ ngoài thư sinh, sự chu đáo và khả năng nấu ăn tuyệt vời, anh đã bước vào cuộc đời cô như một điểm tựa vững chãi nhất. Trong bối cảnh cha mẹ bỏ mặc, anh trai đi du học, Ninh Uyển vốn đầy sợ hãi và cô độc đã tìm thấy sự an ủi nơi anh. Hai tâm hồn thiếu thốn tình thương cứ thế nương tựa vào nhau; anh bảo vệ cô khỏi những trận bắt nạt, những gã côn đồ, và trở thành \"người nhà\" duy nhất đồng hành cùng cô qua mọi biến cố. \r\n\r\nTình cảm ngây ngô của tuổi trẻ dần nảy nở, Ninh Uyển vụng về gấp 1.000 bông hồng giấy với mong ước dành mọi điều tốt đẹp nhất cho người mình yêu. Nhưng cô không biết rằng, với một người mồ côi luôn tự hỏi \"tại sao mình bị bỏ lại\" như Tống Thanh Yến, sự tồn tại và lòng nhiệt thành của cô chính là món quà vô giá nhất. Tưởng chừng hạnh phúc sẽ trọn vẹn, nhưng bi kịch ập đến vào năm anh 22 tuổi: Tống Thanh Yến đã hy sinh mạng sống để cứu Ninh Uyển ngay trước mắt cô. Sự ra đi của anh để lại một khoảng trống không thể lấp đầy, buộc Ninh Uyển phải học cách bước tiếp giữa thực tại nghiệt ngã theo tâm nguyện cuối cùng của người cô yêu nhất.', 355, 395, 'ngo-ngo-dong.webp', 43, 0, '2026-03-08 07:00:00', 20.00),
(8, 23, '\"Từ Tốt Đến Vĩ Đại\" - Jim Collins', 'tu-tot-den-vi-dai', '\"Từ Tốt Đến Vĩ Đại\" là kết quả của công trình nghiên cứu đồ sộ kéo dài 5 năm, nhằm trả lời câu hỏi hóc búa: Làm thế nào những công ty bình thường có thể bứt phá để trở thành vĩ đại và duy trì sự xuất sắc đó trong ít nhất 15 năm? Jim Collins cùng đội ngũ của mình đã bóc tách những quan niệm sai lầm về sự thành công và giới thiệu những khái niệm mang tính nền tảng như: Nhân sự đi trước - Công việc theo sau, Khái niệm Con Nhím và Nhà lãnh đạo cấp độ 5.', 'Từ Tốt Đến Vĩ Đại là kết quả của công trình nghiên cứu đồ sộ kéo dài 5 năm, nhằm trả lời câu hỏi hóc búa: Làm thế nào những công ty bình thường có thể bứt phá để trở thành vĩ đại và duy trì sự xuất sắc đó trong ít nhất 15 năm? Jim Collins cùng đội ngũ của mình đã bóc tách những quan niệm sai lầm về sự thành công và giới thiệu những khái niệm mang tính nền tảng như: Nhân sự đi trước - Công việc theo sau, Khái niệm Con Nhím và Nhà lãnh đạo cấp độ 5.', 200, 220, '09462021_024609.webp', 53, 0, '2026-03-08 07:00:00', 20.00),
(9, 23, '\"Thế Mới Là Marketing! - This Is Marketing\" - Seth Godin', 'this-is-marketing', 'Một cách tiếp cận mang tính “thay đổi cuộc chơi đối” với MARKETING, KINH DOANH và QUẢNG CÁO.', 'Dù dịch vụ hay sản phẩm của bạn là gì đi nữa, thì cuốn sách này sẽ chỉ cho bạn cách tô điểm “diện mạo” sao cho thật hấp dẫn, từ đó thu hút được những khách hàng tiềm năng mong muốn nhất. Seth đã kết hợp tài tình tầm nhìn, quan sát và những ví dụ đáng nhớ để chỉ cho bạn cách tô điểm “diện mạo” sao cho thật hấp dẫn, từ đó thu hút được những khách hàng tiềm năng mong muốn nhất. Seth đã kết hợp tài tình tầm nhìn, quan sát và những ví dụ đáng nhớ để chỉ cho bạn: \r\nGây dựng chữ tín và thiện cảm với khách hàng mục tiêu.\r\n	Làm chủ nghệ thuật định vị - xác định cả khách hàng mục tiêu cũng như khách hàng không phải mục tiêu.\r\n	Tìm ra cách tốt nhất để đạt được các mục tiêu marketing là giúp những người khác trở thành người họ muốn trở thành.\r\n	Tại sao những phương pháp quảng cáo, marketing và quảng bá thương hiệu không còn hiệu quả.\r\n	Vai trò quan trọng của áp lực trước bất cứ quyết định mua (không mua) hàng… \r\n\r\nHãy làm mọi điều tuyệt vời cho những người bạn quan tâm và cuốn sách này sẽ chỉ cho bạn cách thực hiện điều đó!', 115, 120, 'the-moi-la-marketing_this-is-marketing.webp', 33, 0, '2026-03-08 07:00:00', 20.00),
(10, 23, '\"Người Bán Hàng Vĩ Đại Nhất Thế Giới\" - Og Mandino', 'nguoi-ban-hang-vi-dai-nhat-the-gioi', 'Thông qua câu chuyện đầy cảm hứng về hành trình của cậu bé chăn lạc đà Hafid trở thành người bán hàng vĩ đại, cuốn sách hé lộ 10 cuộn da dê cổ xưa chứa đựng những bí mật để đạt được thành công. Thay vì dạy những mánh khóe thương trường, Og Mandino tập trung vào việc rèn luyện kỷ luật, tình yêu thương và sự kiên trì để thay đổi thói quen và vận mệnh của một con người.', '\"Người Bán Hàng Vĩ Đại Nhất Thế Giới\" kể về câu chuyện của Hafid, một cậu bé chăn lạc đà nghèo, ở Jerusalem thời cổ đại.  Xuất thân là một cậu nhóc trông lạc đà cho đoàn buôn của Pathros, nhưng với quyết tâm đổi đời, muốn cải thiện vị trí của mình trong cuộc sống, Hafid luôn nuôi ước mơ được trở thành người bán hàng. Cậu tin chỉ như thế mình mới có cơ hội trở nên giàu có và thành công. \r\n\r\nGiống như nhiều người theo đuổi đam mê khác, trong suốt hành trình ấy đôi lúc Hafid đã nghĩ đến việc quay trở về với công việc chăn lạc đà, kiếm những đồng xu lẻ sống qua ngày. Biết bao nhiêu mối suy tư nghi ngờ, thương tiếc bản thân đã nảy ra trong tâm trí và bủa vây lấy cậu, nhưng với ý chí và quyết tâm, cuối cùng Hafid cũng trở thành người bán hàng tài năng nhất lúc bấy giờ.\r\n\r\nBí mật nào đã làm nên thành công? Đó chính là những nguyên tắc được một thương nhân giàu có và thành công truyền lại và Hafid đã giữ kỹ trong 10 cuộn giấy da trong suốt hơn ba thập kỉ qua. Với Hafid, những thứ giản dị này còn quý hơn cả kim cương. Nhờ áp dụng những nguyên tắc trong cuộn giấy da đó mà Hafid được mệnh danh là “Người bán hàng vĩ đại nhất thế giới”. Tuy nhiên, sách không chỉ dạy bạn cách “bán hàng”, mà nó còn là một cuốn sách dạy bạn làm người, giúp bạn trở thành người “vĩ đại nhất” trong lĩnh vực mà bạn chọn.', 115, 130, 'nguoi-ban-hang-vi-dai.webp', 26, 0, '2026-03-08 07:00:00', 20.00),
(11, 26, '\"Chú Thuật Hồi Chiến - Tập 26 - Về Phương Nam\" - Gege Akutami', 'jintsu-kaisen_chap26', 'Chú Thuật Hồi Chiến - Tập 26 - Về Phương Nam', 'Cuộc chiến vô tiền khoáng hậu giữa người mạnh nhất lịch sử và người mạnh nhất đương thời…!! Cùng lúc triển khai lãnh địa, liên tục phục hồi thuật thức đã cạn kiệt, Sukuna triệu hồi Ma Khư La, còn lãnh địa của Gojo đã bị vô hiệu hoá. Cán cân đang dần nghiêng về một phía...!?', 45, 50, 'jintsu-kaisen_tap-26.webp', 36, 0, '2026-03-08 07:00:00', 20.00),
(12, 26, '\"Chú Thuật Hồi Chiến - Tập 16 - Biến Cố Shibuya - Bế Môn\" - Gege Akutami', 'jintsu-kaisen_chap16', 'Chú Thuật Hồi Chiến - Tập 16', 'Geto đã hấp thụ Mahito và tiết lộ một phần âm mưu của mình. Cục diện của biến cố Shibuya đã đi đến hồi kết, trong lúc các chú thuật sư tập hợp lại, liệu Choso có phát hiện ra chân tướng “kẻ chủ mưu” kí sinh trên thể xác của Geto!? \r\nSự diệt vong và hỗn độn đặt dấu chấm hết cho biến cố, thế giới đột ngột thay đổi!!', 62, 74, 'jintsu-kaisen_tap-16.jpg', 61, 0, '2026-03-08 07:00:00', 20.00),
(13, 26, '\"Chú Thuật Hồi Chiến - Tập 2\" - Gege Akutami', 'jintsu-kaisen_chap2', 'Chú Thuật Hồi Chiến - Tập 2', 'Chú thai bất ngờ xuất hiện tại trại cải tạo thanh thiếu niên. Nhóm Itadori, học sinh năm Nhất trường chuyên chú thuật, được cử đi cứu những người đang mắc kẹt bên trong. Nhưng chú thai sau khi hóa thành chú linh đã tấn công cả nhóm. Trước tình thế hiểm nghèo, Itadori đã trao quyền kiểm soát cơ thể cho Sukuna với hi vọng sẽ hạ gục chú linh, song...!?', 50, 48, '8935244867916.webp', 20, 0, '2026-03-08 07:00:00', 20.00),
(14, 26, '\"Chú Thuật Hồi Chiến - Tập 23 - Sao Và Dầu\" - Gege Akutami', 'jintsu-kaisen_chap23', 'Chú Thuật Hồi Chiến - Tập 23', 'Sukuna tự xưng là “Thiên thần sa ngã”, là mục tiêu của “Thiên thần”. Trong khi nhóm Itadori còn đang mơ hồ về ý nghĩa của câu nói đó thì Tử Diệt Hồi Du ngày càng hỗn loạn bởi âm mưu của Kenjaku tại các quốc gia…!! Và cuối cùng, Kenjaku cũng đến được Hoằng Tinh Cung nơi Tengen đang trú ẩn!?', 105, 130, 'jintsu-kaisen_tap-23.webp', 37, 0, '2026-03-08 07:00:00', 23.00),
(15, 26, '\"Doraemon - Nobita Và Cuộc Phiêu Lưu Vào Thế Giới Trong Tranh\" - Fujiko F Fujio', 'cuoc-phieu-luu-vao-the-gioi-trong-tranh', 'Cảm xúc từ bộ phim điện ảnh nay sống lại qua từng trang truyện tranh!', 'Thông qua món bảo bối mới của Doraemon, cả nhóm bạn bước thế giới trong một bức tranh nổi tiếng và bắt gặp cô bạn bí ẩn tên Claire. Với lời mời của Claire, cả nhóm cùng đến thăm công quốc Artoria, nơi ẩn giấu một viên ngọc quý mang tên Artoria Blue đang ngủ yên. Trên hành trình tìm kiếm viên ngọc, nhóm bạn Doraemon phát hiện một truyền thuyết về sự hủy diệt của thế giới, và truyền thuyết đó dường như đang sống dậy! Liệu cả nhóm có thể phá hủy lời nguyền này và bảo vệ thế giới?', 90, 99, 'doraemon-nobita-va-cuoc-phieu-luu-vao-the-gioi-trong-tranh.webp', 14, 0, '2026-03-08 07:00:00', 20.00),
(16, 26, 'BlueLock - Muneyuki Kaneshiro, Yusuke Nomura', 'blue-lock-chap29', 'KHAI MẠC TRẬN ĐẤU CUỐI CÙNG GIỮA ĐỨC VÀ PHÁP! CUỘC ĐỤNG ĐỘ SIÊU CẤP GIỮA NHỮNG KẺ BẤT BẠI NHẰM GIÀNH LẤY CHỨC VÔ ĐỊCH TRỌN VẸN!!', 'Trận chung kết của “đại chiến tân anh hùng” cuối cùng cũng bắt đầu! Đương lúc những pha tấn công - phòng ngự diễn ra nhanh chóng và dữ dội, Shido cùng Charles của đội Pháp do Loki dẫn dắt đã triển khai một đợt tấn công hoàn toàn mới. Bên kia chiến tuyến, để chặn đợt tấn công dữ dội của đội Pháp, đội Đức với những cái tôi sắp thức tỉnh đang lên kế hoạch tấn công! Và Isagi, người bị cả Kaiser lẫn Rin nhắm đến, đang lao tới trước khung thành để thể hiện “màn trình diễn tốt nhất” của bản thân! Thoát khỏi sự hỗn loạn, tập trung vào đòn tấn công làm thay đổi diễn biến trận đấu nào!!', 68, 78, 'bluelock-tap_29.jpg', 9, 0, '2026-03-08 07:00:00', 20.00),
(45, 22, '\"Nhà giả kim\" – Paulo Coelho', 'nha-gia-kim--paulo-coelho-12-28', '\"Nhà giả kim\" kể về hành trình của một chàng trai trẻ chăn cừu tên Santiago từ Tây Ban Nha đến sa mạc Ai Cập để tìm kiếm kho báu ẩn giấu. Trên đường đi, Santiago gặp gỡ nhiều người khác nhau và học hỏi những bài học quý báu về cuộc sống. Cuối cùng, anh phát hiện ra rằng kho báu thực sự không phải là vàng bạc, mà chính là sự trưởng thành và hiểu biết về chính mình cũng như ý nghĩa cuộc sống.', '\"Nhà giả kim\" là một tiểu thuyết truyền cảm hứng, đậm chất triết lý, kể về hành trình khám phá bản thân và theo đuổi ước mơ của mình. Cuốn sách nhấn mạnh tầm quan trọng của việc lắng nghe tiếng gọi của trái tim và không ngừng nỗ lực để đạt được những mục tiêu lớn lao. Paulo Coelho đã khéo léo sử dụng các yếu tố của văn hóa, tôn giáo và triết học để tạo nên một câu chuyện giàu ý nghĩa và đầy cảm hứng, gợi mở cho người đọc nhiều suy ngẫm về cuộc sống.', 311, 373, '1740889351.png', 17, 0, '2025-03-02 04:22:31', 20.00),
(47, 22, '\"Tôi thấy hoa vàng trên cỏ xanh\" – Nguyễn Nhật Ánh', 'toi-thay-hoa-vang-tren-co-xanh--nguyen-nhat-anh-80', '\"Tôi thấy hoa vàng trên cỏ xanh\" là một câu chuyện đầy cảm xúc về tuổi thơ của hai anh em Thiều và Tường sống tại một ngôi làng nhỏ ở Việt Nam. Câu chuyện diễn ra trong những năm 1980, khi đất nước còn khó khăn và thiếu thốn. Thiều và Tường cùng nhau trải qua nhiều kỷ niệm vui buồn, từ những cuộc phiêu lưu trong thế giới tưởng tượng, những trò nghịch ngợm, cho đến những tình cảm chân thành dành cho bạn bè và gia đình. Cuốn sách không chỉ tái hiện lại hình ảnh tuổi thơ hồn nhiên mà còn chứa đựng những bài học về tình yêu, lòng nhân ái và sự tha thứ.', '\"Tôi thấy hoa vàng trên cỏ xanh\" là một tác phẩm đầy chất thơ và đậm đà tình cảm của nhà văn Nguyễn Nhật Ánh. Cuốn sách mang đến cho người đọc một cái nhìn chân thật và sâu sắc về tuổi thơ ở vùng quê Việt Nam, với những kỷ niệm đẹp và đầy ý nghĩa. Bằng ngòi bút tinh tế và sự am hiểu sâu sắc về tâm lý trẻ em, Nguyễn Nhật Ánh đã tạo nên một câu chuyện dễ thương và đầy cảm động, gợi nhắc người đọc về những giá trị truyền thống và tình cảm gia đình quý báu.', 701, 841, '1740904106.png', 33, 0, '2025-03-02 08:28:26', 20.00),
(50, 22, '\"Những người khốn khổ\" – Victor Hugo', 'nhung-nguoi-khon-kho--victor-hugo-56', '\"Những người khốn khổ\" (Les Misérables) là một tiểu thuyết nổi tiếng của nhà văn Victor Hugo, kể về cuộc đời của Jean Valjean, một người đàn ông nghèo khó bị kết án và bị giam cầm vì tội ăn cắp một ổ bánh mì để nuôi em gái và các cháu. Sau khi được thả, Jean Valjean trải qua nhiều biến cố và gặp gỡ nhiều nhân vật khác nhau như Fantine, Cosette, Marius và Javert. Ông cố gắng chuộc lỗi và thay đổi cuộc đời, nhưng luôn bị ám ảnh bởi quá khứ và sự truy đuổi của viên thanh tra Javert.\r\n\r\nCâu chuyện diễn ra trong bối cảnh xã hội Pháp thế kỷ 19, với những cuộc cách mạng và biến đổi lớn lao. Cuộc sống của các nhân vật phản ánh những khó khăn, đau khổ và nỗ lực không ngừng nghỉ để tìm kiếm hạnh phúc và công lý.', '\"Những người khốn khổ\" là một tác phẩm văn học kinh điển, miêu tả sâu sắc về cuộc sống của những con người bị lãng quên và đau khổ trong xã hội. Cuốn sách thể hiện sự đồng cảm sâu sắc của Victor Hugo đối với những người khốn khó và bất hạnh, đồng thời lên án những bất công và áp bức của xã hội. Những nhân vật trong cuốn sách được xây dựng một cách tỉ mỉ và phức tạp, mỗi người đều có những nỗi đau và khát vọng riêng.\r\n\r\nTác phẩm không chỉ là một câu chuyện về cuộc đời Jean Valjean mà còn là một bức tranh toàn cảnh về xã hội Pháp thế kỷ 19, với những biến đổi về chính trị, kinh tế và xã hội. \"Những người khốn khổ\" đã truyền cảm hứng cho nhiều thế hệ và được chuyển thể thành nhiều bộ phim, vở nhạc kịch và tác phẩm nghệ thuật khác.', 459, 500, '1740904594.png', 32, 0, '2025-03-02 08:36:34', 20.00),
(51, 23, '\"Cha giàu cha nghèo\" – Robert Kiyosaki', 'cha-giau-cha-ngheo--robert-kiyosaki-35', '\"Cha giàu cha nghèo\" (Rich Dad Poor Dad) là một cuốn sách về tài chính cá nhân được viết bởi Robert Kiyosaki. Cuốn sách kể về những bài học mà tác giả đã học được từ hai người cha khác nhau: người cha ruột (Cha nghèo) và cha của bạn thân (Cha giàu). Cha nghèo là một công chức với tư duy truyền thống về tiền bạc và công việc ổn định, trong khi Cha giàu là một doanh nhân thành đạt với tư duy khác biệt về đầu tư và tài chính.\r\n\r\nQua những câu chuyện và bài học từ hai người cha, Robert Kiyosaki chia sẻ những nguyên tắc cơ bản về tài chính cá nhân, cách quản lý tiền bạc, đầu tư và xây dựng sự giàu có. Ông nhấn mạnh tầm quan trọng của giáo dục tài chính và sự tự do tài chính.', '\"Cha giàu cha nghèo\" là một tác phẩm nổi tiếng về tài chính cá nhân, giúp người đọc thay đổi cách nhìn về tiền bạc và đầu tư. Cuốn sách cung cấp những kiến thức và kỹ năng cần thiết để quản lý tài chính cá nhân, tạo ra nguồn thu nhập thụ động và đạt được sự tự do tài chính. Robert Kiyosaki sử dụng ngôn ngữ đơn giản, dễ hiểu, kết hợp với những ví dụ thực tế và câu chuyện cá nhân để minh họa cho các khái niệm và bài học.\r\n\r\nCuốn sách đã truyền cảm hứng cho hàng triệu người trên khắp thế giới, giúp họ cải thiện tình hình tài chính và đạt được những mục tiêu lớn lao trong cuộc sống. \"Cha giàu cha nghèo\" không chỉ là một cuốn sách về tài chính, mà còn là một lời khuyên quý giá về việc thay đổi tư duy và hành động để đạt được thành công.', 650, 700, '1740904883.png', 45, 0, '2025-03-02 08:41:23', 20.00),
(52, 23, '\"Đắc nhân tâm\" – Dale Carnegie', 'dac-nhan-tam--dale-carnegie-39', '\"Đắc nhân tâm\" (How to Win Friends and Influence People) là một cuốn sách nổi tiếng về nghệ thuật giao tiếp và lãnh đạo, được viết bởi Dale Carnegie. Cuốn sách bao gồm nhiều nguyên tắc và kỹ thuật giúp cải thiện các mối quan hệ xã hội, làm cho người khác thích mình và ảnh hưởng đến họ một cách tích cực. Những bài học này dựa trên những tình huống thực tế và trải nghiệm cá nhân của tác giả, giúp người đọc áp dụng dễ dàng vào cuộc sống hàng ngày.\r\n\r\nCuốn sách chia thành bốn phần chính: (1) Những cách thức để làm cho mọi người thích mình, (2) Các phương pháp thuyết phục người khác theo quan điểm của mình, (3) Cách thay đổi người khác mà không gây ra sự phản kháng, và (4) Các quy tắc để cải thiện mối quan hệ trong công việc và cuộc sống.', '\"Đắc nhân tâm\" là một tác phẩm kinh điển về nghệ thuật giao tiếp và phát triển cá nhân, đã được dịch ra nhiều ngôn ngữ và bán chạy hàng đầu trên thế giới. Dale Carnegie đã khéo léo kết hợp lý thuyết và ví dụ thực tế để cung cấp cho người đọc những kỹ năng cần thiết để xây dựng và duy trì các mối quan hệ tốt đẹp.\r\n\r\nCuốn sách không chỉ giúp người đọc hiểu rõ hơn về tâm lý con người mà còn hướng dẫn cách để tạo ra sự đồng cảm, tôn trọng và tin tưởng trong giao tiếp. Những nguyên tắc được trình bày trong \"Đắc nhân tâm\" không chỉ áp dụng trong cuộc sống cá nhân mà còn rất hữu ích trong môi trường công việc và kinh doanh.', 750, 800, '1740905039.png', 39, 0, '2025-03-02 08:43:59', 20.00),
(53, 23, '\"Nghệ thuật tư duy rành mạch\" – Rolf Dobelli', 'nghe-thuat-tu-duy-ranh-mach--rolf-dobelli-47', '\"Nghệ thuật tư duy rành mạch\" (The Art of Thinking Clearly) của Rolf Dobelli là một cuốn sách tập hợp những sai lầm thường gặp trong tư duy hàng ngày và cách để tránh chúng. Tác giả phân tích 99 lỗi tư duy phổ biến mà chúng ta thường mắc phải, từ các thiên kiến nhận thức đến những sai lầm trong việc ra quyết định. Mỗi chương trong cuốn sách tập trung vào một lỗi tư duy cụ thể, giải thích nó và cung cấp các ví dụ minh họa cùng những cách thức để tránh sai lầm đó.', '\"Nghệ thuật tư duy rành mạch\" là một cuốn sách hữu ích và dễ tiếp cận cho bất kỳ ai quan tâm đến việc cải thiện khả năng tư duy và ra quyết định. Rolf Dobelli đã sử dụng ngôn ngữ rõ ràng, dễ hiểu, kết hợp với những ví dụ thực tế và nghiên cứu khoa học để minh họa các lỗi tư duy. Cuốn sách không chỉ giúp người đọc nhận ra những sai lầm trong tư duy mà còn cung cấp những gợi ý thực tế để tránh chúng, từ đó nâng cao chất lượng quyết định và hiệu suất làm việc.\r\n\r\nCuốn sách đã được nhiều người đón nhận và đánh giá cao vì khả năng giúp người đọc hiểu rõ hơn về cách tư duy và ra quyết định. \"Nghệ thuật tư duy rành mạch\" không chỉ là một cuốn sách về khoa học nhận thức mà còn là một công cụ hữu ích để cải thiện cuộc sống cá nhân và công việc.', 450, 500, '1740905228.jpg', 13, 0, '2025-03-02 08:47:08', 20.00),
(54, 23, '\"Khởi nghiệp tinh gọn\" – Eric Ries', 'khoi-nghiep-tinh-gon--eric-ries-52', '\"Khởi nghiệp tinh gọn\" (The Lean Startup) là một cuốn sách nổi tiếng của Eric Ries, giới thiệu về phương pháp khởi nghiệp dựa trên việc thử nghiệm, học hỏi và cải tiến liên tục. Cuốn sách tập trung vào việc phát triển các sản phẩm và dịch vụ mới một cách hiệu quả và tiết kiệm, bằng cách sử dụng các nguyên tắc của tư duy tinh gọn và cải tiến liên tục.\r\n\r\nPhương pháp Khởi nghiệp tinh gọn giúp các doanh nghiệp khởi nghiệp tăng cơ hội thành công bằng cách tập trung vào việc xây dựng các phiên bản thử nghiệm tối thiểu (Minimum Viable Product - MVP) và thu thập phản hồi từ khách hàng để nhanh chóng điều chỉnh và cải tiến sản phẩm. Cuốn sách cũng giới thiệu các khái niệm quan trọng như \"vòng lặp xây dựng - đo lường - học hỏi\" và \"các chỉ số đổi mới\".', '\"Khởi nghiệp tinh gọn\" là một cuốn sách đột phá về cách thức khởi nghiệp, giúp người đọc hiểu rõ hơn về cách xây dựng và phát triển một doanh nghiệp khởi nghiệp thành công. Eric Ries đã đưa ra một phương pháp tiếp cận mới mẻ và hiệu quả, giúp giảm thiểu rủi ro và lãng phí trong quá trình khởi nghiệp.\r\n\r\nCuốn sách không chỉ dành riêng cho các doanh nhân khởi nghiệp, mà còn hữu ích cho các nhà quản lý và lãnh đạo trong các tổ chức lớn muốn áp dụng tư duy tinh gọn vào quá trình phát triển sản phẩm và dịch vụ. \"Khởi nghiệp tinh gọn\" đã trở thành một nguồn cảm hứng và hướng dẫn quý giá cho nhiều thế hệ doanh nhân và nhà quản lý trên toàn thế giới.', 542, 651, '1740905358.png', 58, 0, '2025-03-02 08:49:18', 20.00),
(55, 24, '\"Lược sử thời gian\" – Stephen Hawking', 'luoc-su-thoi-gian--stephen-hawking-28', '\"Lược sử thời gian\" là một cuốn sách khoa học phổ thông do nhà vật lý lý thuyết Stephen Hawking viết. Cuốn sách cung cấp một cái nhìn tổng quan về lịch sử vũ trụ, từ vụ nổ Big Bang cho đến các lỗ đen và lý thuyết dây. Stephen Hawking giải thích những khái niệm phức tạp về thời gian, không gian, và bản chất của vũ trụ một cách dễ hiểu và hấp dẫn. Cuốn sách cũng đề cập đến những câu hỏi sâu sắc về nguồn gốc và số phận của vũ trụ, từ đó khơi dậy sự tò mò và khuyến khích người đọc tìm hiểu thêm về thế giới xung quanh.', '\"Lược sử thời gian\" là một tác phẩm kinh điển về khoa học phổ thông, giúp người đọc tiếp cận với những khái niệm khoa học phức tạp một cách dễ dàng và thú vị. Bằng cách sử dụng ngôn ngữ giản dị và hình ảnh minh họa, Stephen Hawking đã biến những ý tưởng khó hiểu trở nên dễ hiểu và dễ tiếp thu hơn. Cuốn sách không chỉ giải thích các hiện tượng vật lý như lỗ đen, lỗ sâu, và vũ trụ giãn nở, mà còn đưa ra những vấn đề triết học về thời gian và không gian.\r\n\r\nCuốn sách đã truyền cảm hứng cho nhiều thế hệ nhà khoa học và người yêu khoa học, khuyến khích họ tìm hiểu và khám phá những bí ẩn của vũ trụ. \"Lược sử thời gian\" không chỉ là một cuốn sách về khoa học, mà còn là một hành trình tri thức, mở ra những chân trời mới và kích thích tư duy sáng tạo.', 604, 725, '1740905520.png', 42, 0, '2025-03-02 08:52:00', 20.00),
(57, 24, '\"Code: The Hidden Language of Computer Hardware and Software\" – Charles Petzold', 'code-the-hidden-language-of-computer-hardware-and-software--charles-petzold-60', '\"Code: The Hidden Language of Computer Hardware and Software\" là một cuốn sách cung cấp cái nhìn sâu sắc về cách máy tính hoạt động ở cả mức phần cứng và phần mềm. Charles Petzold giải thích các khái niệm phức tạp về máy tính bằng cách sử dụng các ví dụ từ các công nghệ lịch sử như mã Morse, chữ nổi Braille và logic Boolean. Cuốn sách bắt đầu từ những nguyên lý cơ bản nhất và dần dần xây dựng lên các khái niệm phức tạp hơn, giúp người đọc hiểu rõ hơn về cách máy tính xử lý thông tin.', '\"Code: The Hidden Language of Computer Hardware and Software\" là một tác phẩm quan trọng trong lĩnh vực khoa học máy tính, giúp người đọc tiếp cận với những khái niệm phức tạp một cách dễ dàng và thú vị. Charles Petzold sử dụng ngôn ngữ rõ ràng, dễ hiểu và kết hợp với nhiều ví dụ minh họa để giải thích các khái niệm về điện tử, mạch logic, và cách máy tính thực hiện các phép tính. Cuốn sách không chỉ giúp người đọc hiểu rõ hơn về cách máy tính hoạt động mà còn mang lại cảm giác ngưỡng mộ trước sự kỳ diệu và phức tạp của công nghệ.', 232, 278, '1740905915.jpg', 67, 0, '2025-03-02 08:58:35', 20.00),
(59, 25, '\"Sapiens: Lược sử loài người\" – Yuval Noah Harari', 'sapiens-luoc-su-loai-nguoi--yuval-noah-harari-35-35', '\"Sapiens: Lược sử loài người\" là một cuốn sách nổi tiếng của Yuval Noah Harari, trình bày về quá trình phát triển và tiến hóa của loài người từ hàng triệu năm trước đến hiện tại. Cuốn sách bắt đầu từ thời kỳ xuất hiện của Homo sapiens và tiếp tục qua các giai đoạn quan trọng như Cách mạng Nhận thức, Cách mạng Nông nghiệp, và Cách mạng Khoa học. Harari phân tích những thay đổi lớn trong xã hội loài người và những yếu tố đã định hình nên thế giới hiện đại, từ ngôn ngữ, văn hóa đến kinh tế và chính trị.', '\"Sapiens: Lược sử loài người\" là một tác phẩm khoa học phổ thông đầy cuốn hút và sắc bén, giúp người đọc hiểu rõ hơn về quá trình tiến hóa và phát triển của loài người. Yuval Noah Harari đã sử dụng ngôn ngữ dễ hiểu và lối viết kể chuyện hấp dẫn để trình bày những khái niệm phức tạp về lịch sử và xã hội học. Cuốn sách không chỉ cung cấp những kiến thức khoa học mà còn khơi dậy những suy ngẫm sâu sắc về bản chất của loài người và tương lai của chúng ta.\r\n\r\nCuốn sách đã nhận được nhiều lời khen ngợi từ các nhà phê bình và bạn đọc trên khắp thế giới, và đã được dịch ra nhiều ngôn ngữ. \"Sapiens: Lược sử loài người\" là một tài liệu quý giá cho bất kỳ ai muốn tìm hiểu về lịch sử loài người và những yếu tố đã định hình nên thế giới hiện đại.', 334, 401, '1740906401.jpg', 110, 0, '2025-03-02 09:06:41', 20.00),
(60, 26, '\"Nobita và chuyến tàu tốc hành ngân hà\" – Fujiko F. Fujio', 'nobita-va-chuyen-tau-toc-hanh-ngan-ha--fujiko-f-fujio-16', '\"Nobita và chuyến tàu tốc hành ngân hà\" (Nobita and the Galaxy Super-Express) là một câu chuyện trong loạt truyện tranh Doraemon. Trong câu chuyện này, Doraemon sử dụng bảo bối của mình để đưa Nobita, Shizuka, Suneo và Jaian tham gia vào một chuyến tàu vũ trụ đặc biệt đi qua các hành tinh trong dải Ngân Hà. Trong hành trình, họ khám phá những hành tinh kỳ lạ, gặp gỡ những sinh vật và nền văn minh mới, cũng như trải qua nhiều cuộc phiêu lưu đầy kịch tính.\r\n\r\nCâu chuyện trở nên gay cấn khi họ phải đối mặt với một thế lực đen tối có âm mưu chiếm đoạt tàu và gây nguy hiểm cho hành khách. Với sự giúp đỡ của Doraemon và các bảo bối thần kỳ, nhóm bạn cùng nhau vượt qua những thử thách, giải cứu tàu và đảm bảo sự an toàn cho mọi người.', '\"Nobita và chuyến tàu tốc hành ngân hà\" là một câu chuyện phiêu lưu hấp dẫn, kết hợp giữa yếu tố khoa học viễn tưởng và tình bạn. Truyện không chỉ mang đến những phút giây hồi hộp và hài hước mà còn truyền tải những thông điệp về tình bạn, lòng dũng cảm và tinh thần đoàn kết. Qua mỗi hành trình, nhóm bạn Nobita học được nhiều bài học quý báu và trưởng thành hơn.', 64, 80, '1740906770.jpg', 84, 0, '2025-03-02 09:12:50', 25.00),
(61, 26, '\"Nobita và lịch sử khai phá vũ trụ\" – Fujiko F. Fujio', 'nobita-va-lich-su-khai-pha-vu-tru--fujiko-f-fujio-76', '\"Nobita và lịch sử khai phá vũ trụ\" là một phần trong loạt truyện tranh Doraemon. Trong câu chuyện này, Doraemon, Nobita và các bạn của họ tham gia vào một cuộc phiêu lưu kỳ thú trong vũ trụ. Họ đến hành tinh Koya Koya, nơi đang bị đe dọa bởi bọn xâm lược từ không gian. Để bảo vệ hành tinh này, nhóm bạn phải sử dụng các bảo bối của Doraemon để chiến đấu chống lại kẻ thù và giải cứu cư dân Koya Koya.\r\n\r\nCâu chuyện là hành trình đầy thử thách và kịch tính, khi nhóm bạn Nobita phải đối mặt với nhiều nguy hiểm và sử dụng trí thông minh cùng lòng dũng cảm để vượt qua.', '\"Nobita và lịch sử khai phá vũ trụ\" là một truyện tranh phiêu lưu hấp dẫn, kết hợp giữa khoa học viễn tưởng và tình bạn. Truyện không chỉ mang lại những phút giây giải trí thú vị mà còn truyền tải những thông điệp về lòng dũng cảm, tinh thần đoàn kết và tình bạn chân thành. Với nét vẽ đặc trưng và cốt truyện cuốn hút, câu chuyện đã ghi dấu ấn trong lòng nhiều độc giả và trở thành một phần của ký ức tuổi thơ.', 35, 42, '1740906969.jpg', 44, 0, '2025-03-02 09:16:09', 20.00),
(62, 26, '\"Nobita vũ trụ phiêu lưu ký\" – Fujiko F. Fujio', 'nobita-vu-tru-phieu-luu-ky--fujiko-f-fujio-66', '\"Nobita vũ trụ phiêu lưu ký\" là một phần trong loạt truyện tranh Doraemon. Trong câu chuyện này, Doraemon, Nobita, Shizuka, Suneo và Jaian tham gia vào một cuộc phiêu lưu đặc biệt trong vũ trụ. Họ sử dụng bảo bối của Doraemon để du hành đến những hành tinh xa xôi và khám phá những thế giới mới lạ. Trên hành trình, nhóm bạn đối mặt với nhiều thử thách và nguy hiểm, nhưng họ cùng nhau vượt qua nhờ vào sự sáng tạo, lòng dũng cảm và tình bạn.\r\n\r\nCâu chuyện trở nên kịch tính khi nhóm bạn phát hiện ra âm mưu xâm lược của một thế lực đen tối và họ phải tìm cách ngăn chặn để bảo vệ các hành tinh và cư dân trong vũ trụ.', '\"Nobita vũ trụ phiêu lưu ký\" là một truyện tranh phiêu lưu hấp dẫn, kết hợp giữa khoa học viễn tưởng và tình bạn. Truyện mang đến những phút giây hồi hộp, thú vị và đầy ý nghĩa, truyền tải những thông điệp về lòng dũng cảm, tinh thần đoàn kết và tình bạn chân thành. Với nét vẽ đặc trưng và cốt truyện cuốn hút, câu chuyện đã ghi dấu ấn trong lòng nhiều độc giả và trở thành một phần không thể thiếu của tuổi thơ.', 47, 35, '1740907144.jpg', 23, 0, '2025-03-02 09:19:04', 20.00),
(63, 26, '\"Thám tử lừng danh Conan tập 98\" – Gosho Aoyama', 'tham-tu-lung-danh-conan-tap-98--gosho-aoyama-92', 'Trong tập 98 của \"Thám tử lừng danh Conan,\" Sera Masumi tiếp tục thăm dò Haibara Ai và đối đầu với Okiya Subaru. Trong khi đó, Conan tiến gần hơn đến việc khám phá chân tướng của \"em gái ngoài lãnh địa\" - Mary. Haneda Shukichi bất ngờ gặp án mạng tại buổi học nhóm shogi, và vụ án diễn biến bất ngờ với nhiều khúc ngoặt, cuối cùng dẫn đến sự xuất hiện của Akai Shuichi. Ngoài ra, tập 98 còn mang đến vụ án giải mật mã của một người giúp việc, nơi cuộc đua phá án giữa Conan và Heiji bắt đầu từ mưu kế của Ooka Momiji.', '\"Thám tử lừng danh Conan tập 98\" là một phần hấp dẫn trong loạt truyện tranh nổi tiếng của Gosho Aoyama. Tập này tiếp tục mang đến những vụ án ly kỳ và những tình tiết bất ngờ, kết hợp giữa yếu tố trinh thám và hành động. Các nhân vật quen thuộc như Conan, Haibara, Sera Masumi, và Akai Shuichi đều có những vai trò quan trọng trong việc giải quyết các vụ án. Truyện không chỉ mang lại những phút giây hồi hộp mà còn truyền tải những thông điệp về tình bạn, lòng dũng cảm và sự thông minh.', 47, 57, '1740907498.jpg', 63, 0, '2025-03-02 09:24:58', 20.00),
(64, 26, '\"Thám tử lừng danh Conan tập \" – Gosho Aoyama', 'tham-tu-lung-danh-conan-tap-100--gosho-aoyama-93', 'Trong tập 100 của \"Thám tử lừng danh Conan,\" các vụ án ly kỳ và các tình tiết hấp dẫn tiếp tục làm say đắm lòng người. Tập này đánh dấu một cột mốc quan trọng khi mối quan hệ giữa Conan/Shinichi và Ran được khám phá sâu hơn. Conan phải đối mặt với nhiều vụ án hóc búa và thách thức mới, từ việc giải mã các bí ẩn trong hội thi đấu karate, điều tra vụ án mạng trong một quán cà phê đến việc vạch trần âm mưu của tổ chức áo đen. Các nhân vật quen thuộc như Haibara Ai, Hattori Heiji, và nhóm thám tử nhí cũng có những vai trò đáng chú ý trong việc hỗ trợ Conan phá án.', '\"Thám tử lừng danh Conan tập 100\" là một phần không thể bỏ lỡ trong loạt truyện tranh nổi tiếng của Gosho Aoyama. Tập này tiếp tục mang đến những vụ án ly kỳ, những tình tiết bất ngờ và sự phát triển của các nhân vật chính. Cốt truyện hấp dẫn kết hợp với nghệ thuật vẽ tinh tế đã tạo nên một tác phẩm truyện tranh đỉnh cao. Ngoài những phút giây hồi hộp và kịch tính, tập truyện còn truyền tải những thông điệp sâu sắc về tình bạn, lòng dũng cảm và sự kiên trì.', 47, 56, '1740907590.jpg', 40, 0, '2025-03-02 09:26:30', 20.00),
(65, 26, '\"Bách khoa toàn thư Pokemon\" – Nhiều tác giả, Lê Thế Đôn dịch', 'bach-khoa-toan-thu-pokemon--nhieu-tac-gia-le-the-don-dich-40-34-67-91-41-96', '\"Bách khoa toàn thư Pokemon\" là một cuốn sách tổng hợp chi tiết và đầy đủ thông tin về thế giới Pokemon, từ các loài Pokemon, khả năng, tiến hóa cho đến các huấn luyện viên và khu vực trong vũ trụ Pokemon. Cuốn sách cung cấp kiến thức toàn diện về mọi khía cạnh của Pokemon, từ những Pokemon đầu tiên cho đến những loài mới nhất. Các thông tin về kỹ năng, thuộc tính, cách bắt và huấn luyện Pokemon cũng được trình bày một cách rõ ràng và dễ hiểu.', '\"Bách khoa toàn thư Pokemon\" là một tài liệu quý giá dành cho những người yêu thích và đam mê thế giới Pokemon. Cuốn sách được biên soạn một cách công phu, với hình ảnh minh họa sống động và thông tin chi tiết về từng loài Pokemon. Người đọc có thể dễ dàng tra cứu thông tin về Pokemon yêu thích của mình, tìm hiểu về nguồn gốc, tiến hóa, đặc điểm và kỹ năng của chúng.\r\n\r\nCuốn sách không chỉ là một công cụ hữu ích cho việc nghiên cứu và tìm hiểu về Pokemon mà còn mang lại niềm vui và cảm hứng cho người đọc. \"Bách khoa toàn thư Pokemon\" đã trở thành một tài liệu không thể thiếu đối với các fan của Pokemon trên toàn thế giới.', 230, 199, '1740907796.png', 100, 0, '2025-03-02 09:29:56', 20.00),
(66, 26, '\"Harry Potter và Hòn đá phù thủy\" – J.K. Rowling', 'harry-potter-va-hon-da-phu-thuy--jk-rowling-13', '\"Harry Potter và Hòn đá phù thủy\" là cuốn sách đầu tiên trong loạt truyện Harry Potter. Câu chuyện bắt đầu khi Harry Potter, một cậu bé mồ côi sống với dì dượng và bị họ đối xử tệ bạc, phát hiện ra mình là phù thủy vào ngày sinh nhật thứ mười một. Harry được mời đến học tại Trường Phù thủy và Pháp sư Hogwarts, nơi cậu nhanh chóng kết bạn với Ron Weasley và Hermione Granger.\r\n\r\nTại Hogwarts, Harry khám phá ra sự thật về cha mẹ mình và quá khứ bi thảm của họ, đồng thời phát hiện ra một bí mật về Hòn đá phù thủy - một vật phẩm ma thuật có thể mang lại sự bất tử. Cậu cùng các bạn trải qua nhiều cuộc phiêu lưu và đối mặt với những nguy hiểm để ngăn chặn kế hoạch chiếm đoạt Hòn đá phù thủy của tên phù thủy hắc ám Voldemort.', '\"Harry Potter và Hòn đá phù thủy\" là một cuốn sách kỳ ảo hấp dẫn và lôi cuốn, mở đầu cho một loạt truyện làm say mê hàng triệu độc giả trên khắp thế giới. Tác giả J.K. Rowling đã xây dựng một thế giới phép thuật đầy màu sắc, với những nhân vật sống động và cốt truyện cuốn hút. Cuốn sách không chỉ mang lại những phút giây giải trí tuyệt vời mà còn truyền tải những thông điệp về tình bạn, lòng dũng cảm và sự hy sinh.', 720, 599, '1740907919.jpg', 56, 0, '2025-03-02 09:31:59', 20.00),
(68, 26, '\"Harry Potter và Phòng chứa bí mật\" – J.K. Rowling', 'harry-potter-va-phong-chua-bi-mat--jk-rowling-13', '\"Harry Potter và Phòng Chứa Bí Mật\" là cuốn sách thứ hai trong loạt truyện Harry Potter. Câu chuyện tiếp tục với năm học thứ hai của Harry tại Trường Phù thủy và Pháp sư Hogwarts. Khi trở lại trường, Harry phát hiện ra rằng có một loạt các vụ tấn công bí ẩn xảy ra khiến nhiều học sinh bị hóa đá. Lời đồn rằng \"Phòng Chứa Bí Mật\" đã được mở lại và một con quái vật nguy hiểm đang được thả ra để tấn công những người không thuần chủng.\r\n\r\nHarry cùng với bạn bè Ron Weasley và Hermione Granger bắt đầu điều tra và phát hiện ra nhiều manh mối quan trọng liên quan đến sự kiện này. Cuối cùng, Harry phải đối mặt với con quái vật trong Phòng Chứa Bí Mật và giải cứu các học sinh bị nạn.', '\"Harry Potter và Phòng Chứa Bí Mật\" là một cuốn sách kỳ ảo hấp dẫn, tiếp tục hành trình phiêu lưu của Harry Potter và những người bạn tại Hogwarts. J.K. Rowling đã tạo ra một câu chuyện lôi cuốn, với những tình tiết bất ngờ và hồi hộp, cùng những bài học về lòng dũng cảm, tình bạn và sự trung thực. Cuốn sách không chỉ mang lại những phút giây giải trí tuyệt vời mà còn truyền tải những thông điệp ý nghĩa về cuộc sống.', 720, 599, '1740908153.jpg', 50, 0, '2025-03-02 09:35:53', 20.00),
(69, 22, '\"Trăm năm cô đơn\" – Gabriel García Márquez', 'tram-nam-co-don--gabriel-garcia-marquez-46', '\"Trăm năm cô đơn\" là một tác phẩm văn học kinh điển của Gabriel García Márquez, kể về cuộc đời của gia đình Buendía trong làng Macondo. Câu chuyện bao trùm bảy thế hệ của gia đình Buendía, từ khi người sáng lập José Arcadio Buendía và vợ ông, Ursula Iguarán, đến Macondo và xây dựng làng. Qua các thế hệ, gia đình Buendía trải qua nhiều biến cố và bi kịch, từ tình yêu và chiến tranh, đến sự cô đơn và mất mát. Tác phẩm kết thúc với sự diệt vong của gia đình Buendía khi hậu duệ cuối cùng, Aureliano, phát hiện ra những tiên tri đã được ghi chép từ trước về số phận của gia đình.', '\"Trăm năm cô đơn\" là một kiệt tác của văn học hiện thực huyền ảo, nổi bật với ngòi bút tinh tế và giàu sức gợi của Gabriel García Márquez. Cuốn sách không chỉ kể về lịch sử và cuộc sống của một gia đình mà còn phản ánh những vấn đề xã hội, văn hóa và chính trị của châu Mỹ Latinh. Với sự kết hợp giữa hiện thực và huyền ảo, tác phẩm mang đến cho người đọc một trải nghiệm độc đáo và sâu sắc, gợi lên nhiều suy ngẫm về cuộc sống, số phận và sự cô đơn của con người.\r\n\r\nCuốn sách đã nhận được nhiều giải thưởng và được coi là một trong những tác phẩm văn học vĩ đại nhất của thế kỷ 20. \"Trăm năm cô đơn\" không chỉ là một câu chuyện về một gia đình, mà còn là một hành trình khám phá những bí ẩn của cuộc sống và tâm hồn con người.', 247, 296, '1740922142.jpg', 110, 0, '2025-03-02 13:29:02', 20.00),
(70, 22, '\"Cánh đồng bất tận\" – Nguyễn Ngọc Tư', 'canh-dong-bat-tan--nguyen-ngoc-tu-86', '\"Cánh đồng bất tận\" là một tập truyện ngắn của nhà văn Nguyễn Ngọc Tư, nổi tiếng với câu chuyện cùng tên \"Cánh đồng bất tận\". Truyện kể về cuộc sống của những con người ở miền Tây Nam Bộ, với những khát vọng, niềm đau và sự đấu tranh trong cuộc sống. Nhân vật chính trong truyện \"Cánh đồng bất tận\" là hai đứa trẻ, Nương và Điền, sống cùng người cha thô bạo và lạnh lùng sau khi mẹ bỏ đi. Họ phải trải qua nhiều khó khăn và biến cố trên những cánh đồng rộng lớn, đối mặt với nỗi cô đơn và bất hạnh. Tập truyện còn bao gồm nhiều câu chuyện khác, mỗi câu chuyện đều mang một màu sắc và thông điệp riêng, nhưng đều xoay quanh cuộc sống và tình cảm của con người.', '\"Cánh đồng bất tận\" là một tác phẩm văn học nổi bật của Nguyễn Ngọc Tư, ghi dấu ấn mạnh mẽ trong lòng độc giả bởi lối viết chân thực, tinh tế và đầy cảm xúc. Tác giả đã khéo léo miêu tả bức tranh cuộc sống ở miền Tây Nam Bộ với những con người bình dị, cảnh vật quen thuộc và những câu chuyện đời thường nhưng đầy ý nghĩa. Từng câu chuyện trong tập truyện mang đến những suy ngẫm sâu sắc về tình cảm gia đình, tình yêu thương và sự hy sinh.\r\n\r\nCuốn sách không chỉ phản ánh hiện thực cuộc sống mà còn truyền tải những thông điệp nhân văn về lòng nhân ái, sự kiên trì và hy vọng. \"Cánh đồng bất tận\" đã nhận được nhiều giải thưởng và được đánh giá cao trong giới phê bình văn học, khẳng định vị trí của Nguyễn Ngọc Tư trong văn học Việt Nam đương đại.', 277, 249, '1740922535.jpg', 57, 0, '2025-03-02 13:35:35', 20.00),
(71, 22, '\"Đồi gió hú\" – Emily Brontë', 'doi-gio-hu--emily-bront-31', '\"Đồi gió hú\" là tiểu thuyết duy nhất của Emily Brontë, kể về câu chuyện tình yêu đầy bi kịch và thù hận giữa Heathcliff và Catherine Earnshaw. Câu chuyện diễn ra tại hai trang trại gần nhau là Wuthering Heights và Thrushcross Grange, nằm trên một vùng đồng quê hoang dã và hẻo lánh của nước Anh. Heathcliff là một cậu bé mồ côi được ông Earnshaw nhận nuôi, nhưng bị đối xử tàn nhẫn bởi con trai của ông, Hindley. Catherine, con gái của ông Earnshaw, và Heathcliff nhanh chóng trở nên thân thiết và phát triển một tình yêu mãnh liệt nhưng không thể nào hòa hợp được.\r\n\r\nSau khi ông Earnshaw qua đời, Hindley tiếp quản Wuthering Heights và đẩy Heathcliff vào cuộc sống khổ cực. Catherine yêu và kết hôn với Edgar Linton, một người giàu có và tinh tế từ Thrushcross Grange, nhưng trái tim cô vẫn thuộc về Heathcliff. Heathcliff, đau khổ và đầy thù hận, trở lại và bắt đầu cuộc trả thù tàn nhẫn, không chỉ đối với Hindley mà còn với thế hệ con cháu của cả hai gia đình.', '\"Đồi gió hú\" là một tác phẩm văn học kinh điển, nổi bật với phong cách viết mạnh mẽ và lối miêu tả tâm lý nhân vật sâu sắc của Emily Brontë. Cuốn sách khám phá những khía cạnh tăm tối của tình yêu, thù hận và sự trả thù, qua đó lột tả những xung đột nội tâm và nỗi đau khổ của các nhân vật. Cảnh sắc hoang dã và cô lập của vùng đồng quê Yorkshire tạo nên bối cảnh hoàn hảo cho câu chuyện đầy ám ảnh và u ám này.\r\n\r\nCuốn sách đã nhận được nhiều lời khen ngợi từ giới phê bình và độc giả, và được coi là một trong những tác phẩm văn học vĩ đại nhất của thế kỷ 19. \"Đồi gió hú\" không chỉ là một câu chuyện tình yêu bi thảm mà còn là một tác phẩm phản ánh những mặt tối của con người và sức mạnh tàn phá của tình yêu và thù hận.', 560, 399, '1740922661.png', 56, 0, '2025-03-02 13:37:41', 20.00),
(72, 22, '\"Lão Hạc\" – Nam Cao', 'lao-hac--nam-cao-91', '\"Lão Hạc\" là một truyện ngắn nổi tiếng của nhà văn Nam Cao, kể về cuộc đời bi kịch của Lão Hạc, một nông dân già sống ở một làng quê nghèo. Lão Hạc sống cô đơn sau khi vợ qua đời và con trai bỏ nhà ra đi vì không có tiền cưới vợ. Lão dành tình cảm đặc biệt cho con chó Vàng, người bạn duy nhất của mình. Tuy nhiên, do không còn đủ tiền nuôi sống cả mình và chó, Lão Hạc buộc phải bán con chó Vàng, điều này khiến ông vô cùng đau khổ và day dứt.\r\n\r\nSau khi bán chó, Lão Hạc quyết định chọn cách tự tử bằng bả chó để tránh gánh nặng cho mọi người xung quanh và giữ lại mảnh đất cho con trai. Cái chết của Lão Hạc không chỉ là sự giải thoát cho ông mà còn là lời tố cáo xã hội phong kiến thối nát, khiến những người nông dân phải chịu đựng cuộc sống cơ cực và bế tắc.', '\"Lão Hạc\" là một tác phẩm nổi bật của Nam Cao, phản ánh chân thực cuộc sống khốn khó của người nông dân Việt Nam trong xã hội phong kiến. Qua câu chuyện về Lão Hạc, tác giả đã thể hiện lòng nhân ái và sự cảm thông sâu sắc đối với những con người nghèo khổ. Nam Cao sử dụng ngôn ngữ giản dị, chân thực và giàu cảm xúc để miêu tả tâm lý nhân vật và cuộc sống đời thường, tạo nên một tác phẩm văn học đầy ý nghĩa và giá trị nhân văn.\r\n\r\nCuốn sách \"Lão Hạc\" không chỉ giúp người đọc hiểu rõ hơn về cuộc sống và số phận của người nông dân trong xã hội phong kiến mà còn truyền tải những thông điệp về lòng nhân ái, tình cảm gia đình và sự hy sinh. Tác phẩm đã trở thành một phần quan trọng của văn học Việt Nam và được nhiều thế hệ độc giả yêu mến.', 899, 750, '1740922867.jpg', 78, 0, '2025-03-02 13:41:07', 20.00),
(73, 22, '\"Thép đã tôi thế đấy\" – Nikolai Ostrovsky', 'thep-da-toi-the-day--nikolai-ostrovsky-50-64-69', '\"Thép đã tôi thế đấy\" là một tiểu thuyết tự truyện của Nikolai Ostrovsky, kể về cuộc đời và sự nghiệp của Pavel Korchagin, một người lính và nhà cách mạng. Câu chuyện bắt đầu từ những năm tuổi thơ đầy khó khăn của Pavel, khi anh sống trong cảnh nghèo khó và chịu đựng sự bất công của xã hội. Sau khi gia nhập Hồng quân trong cuộc Nội chiến Nga, Pavel phải đối mặt với nhiều thử thách gian khổ và những trận chiến khốc liệt.\r\n\r\nBị thương nặng và mất đi sức khỏe, Pavel vẫn không từ bỏ lý tưởng cách mạng và tiếp tục cống hiến cho công cuộc xây dựng xã hội chủ nghĩa. Anh viết sách để chia sẻ kinh nghiệm và truyền cảm hứng cho những người khác, mặc dù phải đấu tranh với bệnh tật và những khó khăn cá nhân.', '\"Thép đã tôi thế đấy\" là một tác phẩm văn học kinh điển của văn học Xô Viết, thể hiện tinh thần kiên cường, dũng cảm và lòng yêu nước của nhân vật chính. Nikolai Ostrovsky đã khéo léo miêu tả cuộc sống gian khổ và sự hy sinh của Pavel Korchagin, từ đó truyền tải thông điệp về ý chí và nghị lực vượt qua khó khăn. Cuốn sách không chỉ là một câu chuyện về cuộc đời của một cá nhân mà còn là một tác phẩm ca ngợi tinh thần cách mạng và sự kiên cường của con người trong cuộc đấu tranh vì lý tưởng cao cả.\r\n\r\n\"Thép đã tôi thế đấy\" đã trở thành một nguồn cảm hứng lớn cho nhiều thế hệ độc giả và được dịch ra nhiều ngôn ngữ trên thế giới. Tác phẩm này không chỉ có giá trị văn học mà còn là một tài liệu quý giá về lịch sử và tinh thần của thời đại cách mạng.', 466, 559, '1740923121.jpg', 80, 0, '2025-03-02 13:45:21', 20.00);
INSERT INTO `products` (`id`, `category_id`, `name`, `slug`, `small_description`, `description`, `original_price`, `selling_price`, `image`, `qty`, `status`, `created_at`, `profit_margin`) VALUES
(74, 22, '\"Giết con chim nhại\" – Harper Lee', 'giet-con-chim-nhai--harper-lee-51-36-98', '\"Giết con chim nhại\" là một tiểu thuyết nổi tiếng của Harper Lee, lấy bối cảnh ở thị trấn nhỏ Maycomb, Alabama, vào những năm 1930. Câu chuyện được kể qua góc nhìn của Scout Finch, một cô bé nghịch ngợm nhưng thông minh, và anh trai Jem Finch. Bố của họ, Atticus Finch, là một luật sư đầy phẩm cách và kiên định. Ông được giao nhiệm vụ bào chữa cho Tom Robinson, một người da đen bị cáo buộc tấn công tình dục một cô gái da trắng.\r\n\r\nTrong suốt quá trình xét xử, gia đình Finch phải đối mặt với sự kỳ thị và thù hận từ cộng đồng. Atticus cố gắng bảo vệ sự công bằng và khẳng định giá trị nhân văn của mỗi con người, bất kể màu da. Câu chuyện không chỉ tập trung vào vụ xét xử mà còn khắc họa cuộc sống hàng ngày của Scout và Jem, cùng những bài học mà họ học được về lòng dũng cảm, sự đồng cảm và công lý.', '\"Giết con chim nhại\" là một tác phẩm văn học kinh điển, thể hiện sự sâu sắc và chân thực trong việc miêu tả những vấn đề xã hội phức tạp như phân biệt chủng tộc, bất công xã hội và lòng dũng cảm. Harper Lee đã xây dựng những nhân vật sống động và đáng nhớ, từ đó truyền tải những thông điệp nhân văn và ý nghĩa.\r\n\r\nCuốn sách được đánh giá cao bởi giới phê bình và đã nhận giải Pulitzer vào năm 1961. \"Giết con chim nhại\" không chỉ là một câu chuyện về cuộc đấu tranh của một người luật sư bảo vệ công lý, mà còn là một bài học về lòng nhân ái, sự đồng cảm và sức mạnh của tình người. Tác phẩm đã trở thành một biểu tượng của văn học Mỹ và được giảng dạy rộng rãi trong các trường học trên khắp thế giới.', 569, 650, '1740923323.png', 75, 0, '2025-03-02 13:48:43', 20.00),
(75, 23, '\"Ngày xưa có một con bò\" - Camilo Cruz', 'ngay-xua-co-mot-con-bo---camilo-cruz-24-83', 'Cuốn sách \"Ngày xưa có một con bò\" của tác giả Camilo Cruz là một câu chuyện ngụ ngôn hiện đại đầy ý nghĩa, tập trung vào việc giúp người đọc nhận diện và loại bỏ những rào cản tâm lý—được ẩn dụ là \"những con bò\"—như sự bao biện, niềm tin sai lầm và thói quen trì hoãn vốn đang kiềm hãm sự thành công của mỗi người. Bằng việc kể về một gia đình nghèo khó trở nên khá giả sau khi mất đi con bò duy nhất, tác giả chứng minh rằng đôi khi chính những thứ chúng ta coi là nguồn sống hay sự an toàn lại là sợi dây trói buộc ta vào cuộc sống tầm thường. Tài liệu không chỉ phân loại các nhóm \"bò\" phổ biến mà còn đưa ra quy trình 5 bước cụ thể để người đọc tự giải phóng bản thân, từ việc nhận dạng những lời biện bạch đến thiết lập các khuôn mẫu hành vi mới, nhằm đánh thức tiềm năng thực sự và kiến tạo một vận mệnh tốt đẹp hơn.', 'Ngày xưa có một con bò của TS. Camilo Cruz là cuốn sách kỹ năng sống kinh điển sử dụng câu chuyện ngụ ngôn về một gia đình nghèo thay đổi vận mệnh sau khi mất đi con bò duy nhất để truyền tải bài học về việc phá bỏ sự an phận. Trong tác phẩm này, \"con bò\" là biểu tượng ẩn dụ cho những lời biện bạch, niềm tin hạn hẹp và thói quen trì hoãn đang kiềm chế năng lực thực sự của mỗi người. Tác giả phân loại chi tiết các nhóm \"bò\" phổ biến như bò \"Tôi có sao đâu\" (sự hài lòng với sự tầm thường), bò \"Đâu phải tại tôi\" (đổ lỗi cho hoàn cảnh), hay bò \"Cầu toàn\" (trì hoãn dưới lớp vỏ chất lượng). Để giải phóng bản thân, tài liệu cung cấp quy trình 5 bước thực tiễn gồm: nhận dạng bò, xác định niềm tin sai lầm ẩn giấu, nhận thức về cái giá phải trả cho sự bao biện, hình dung kết quả tích cực và thiết lập khuôn mẫu hành vi mới. Cuốn sách nhấn mạnh thông điệp về việc nhận 100% trách nhiệm cá nhân để vượt qua sự tầm thường và kiến tạo một cuộc sống vĩ đại.', 17, 22, '1773474268.jpg', 102, 0, '2026-03-14 07:44:28', 30.00),
(76, 24, '\"Lịch Sử Của Lên Men - Cách Thực Phẩm Truyền Thống Nuôi Dưỡng Hệ Vi Sinh\" - Katherine Harmon Courage', 'lich-su-cua-len-men---cach-thuc-pham-truyen-thong-nuoi-duong-he-vi-sinh---katherine-harmon-courage-17-26-32', 'Cuốn sách là một hành trình điền dã kết hợp giữa khoa học và ẩm thực, nơi Katherine Harmon Courage dẫn dắt người đọc đi khắp thế giới—từ những hũ kim chi ở Hàn Quốc đến các xưởng phô mai tại Thụy Sĩ. Bằng giọng văn gần gũi và đầy tò mò, tác giả không chỉ trình bày những dữ liệu khô khan mà còn kể lại những câu chuyện về truyền thống, về cách mà tổ tiên chúng ta đã vô tình \"thuần hóa\" vi khuẩn để bảo quản thực phẩm và nuôi dưỡng cơ thể trước khi tủ lạnh ra đời.', 'Về mặt nội dung, tác phẩm tóm gọn mối quan hệ cộng sinh giữa con người và hệ vi sinh vật (microbiome), nhấn mạnh rằng việc tiêu thụ thực phẩm lên men truyền thống là cách hữu hiệu nhất để tái thiết lập sự đa dạng lợi khuẩn trong đường ruột. Tác giả đối lập sự sạch sẽ quá mức của công nghiệp thực phẩm hiện đại với những giá trị bền vững của phương pháp lên men tự nhiên, từ đó khẳng định rằng việc quay lại với các món ăn \"sống\" không chỉ giúp cải thiện tiêu hóa mà còn tăng cường hệ miễn dịch và sức khỏe tinh thần.', 45, 54, '1773478905.webp', 90, 0, '2026-03-14 09:01:45', 20.00),
(77, 26, '\" Tớ là mèo Pusheen\" - Claire Belton', '-to-la-meo-pusheen-claire-belton-42-18', 'Pusheen là cô mèo mướp xám tròn trịa, biểu tượng của sự đáng yêu và lười biếng với châm ngôn sống xoay quanh việc ăn, ngủ và làm nũng. Cô nàng nổi tiếng toàn cầu nhờ các bộ sticker trên mạng xã hội và loạt sách tranh hài hước, nơi Pusheen thường xuyên \"biến hóa\" thành đủ mọi hình dạng từ nàng tiên cá đến ổ bánh mì. Với tính cách yêu đời và tâm hồn ăn uống bất tận, Pusheen không chỉ là một nhân vật hư cấu mà còn là người bạn tinh thần giúp mọi người cảm thấy thư giãn và vui vẻ hơn.', '\"Hài hước, kì lạ và vô cùng đáng yêu\"\r\n\r\n(Matthew Inman, người sáng lập website The Oatmeal)\r\n\r\nTớ là mèo Pusheen - Cuốn nhật ký xoay quanh cuộc sống của Pusheen - chú mèo Icon nổi tiếng trên mạng xã hội facebook với hơn 7 triệu người hâm mộ. Hãy cùng tìm hiểu những điều khiến Pusheen thích thú và lí do hàng triệu người trót mết vẻ \"tung tăng\" của nàng mèo múp míp, mũm mĩm này nhé!', 0, 0, '1773584114.webp', 0, 0, '2026-03-15 14:15:14', 0.00),
(78, 27, 'qqq', 'qqq-29-61', 'qqq', 'qqq', 16, 19, '1774061033.png', 17, 0, '2026-03-21 01:43:58', 20.00),
(79, 27, 'aaa', 'aaa-61-41', 'aaa', 'aaa', 0, 0, '1774074146.png', 0, 1, '2026-03-21 06:22:26', 0.00),
(80, 27, 'vvv', 'vvv-42-10-68', 'vvvvvv', 'vvvvvvv', 44, 53, '1774075892.png', 10, 0, '2026-03-21 06:51:32', 20.00),
(82, 27, '444', '444-75', '444', '444', 40, 48, '1775267276.png', 95, 0, '2026-04-04 01:47:56', 20.00);

