--
-- Cấu trúc đóng vai cho view `vw_import_history_detail`
-- (See below for the actual view)
--
CREATE TABLE `vw_import_history_detail` (
`id` int(11)
,`product_id` int(11)
,`product_name` varchar(191)
,`quantity_imported` int(11)
,`import_price` decimal(10,2)
,`old_quantity` int(11)
,`old_original_price` decimal(10,2)
,`new_average_price` decimal(10,2)
,`new_selling_price` decimal(10,2)
,`profit_margin` decimal(5,2)
,`admin_name` varchar(191)
,`note` text
,`created_at` timestamp
);

-- --------------------------------------------------------

--
-- Cấu trúc cho view `vw_import_history_detail`
--
DROP TABLE IF EXISTS `vw_import_history_detail`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_import_history_detail`  AS SELECT `ih`.`id` AS `id`, `ih`.`product_id` AS `product_id`, `p`.`name` AS `product_name`, `ih`.`quantity_imported` AS `quantity_imported`, `ih`.`import_price` AS `import_price`, `ih`.`old_quantity` AS `old_quantity`, `ih`.`old_original_price` AS `old_original_price`, `ih`.`new_average_price` AS `new_average_price`, `ih`.`new_selling_price` AS `new_selling_price`, `ih`.`profit_margin` AS `profit_margin`, `u`.`name` AS `admin_name`, `ih`.`note` AS `note`, `ih`.`created_at` AS `created_at` FROM ((`import_history` `ih` left join `products` `p` on(`ih`.`product_id` = `p`.`id`)) left join `users` `u` on(`ih`.`admin_id` = `u`.`id`)) ORDER BY `ih`.`created_at` DESC ;

